action.command:
cd /workspace/project && python3 - <<'PY'
import json
acc={}
for l in open("ob_accounts.txt"):
    p=[x.strip() for x in l.split("|")]
    if len(p)>=3 and p[1].startswith("sk-obs1"):
        acc[p[0]]={"key":p[1],"bal":p[2].replace("$","")}
pro={}
for l in open("ob_results.jsonl"):
    try: d=json.loads(l)
    except: continue
    n=str(d.get("account_number") or "")
    if n and n!="None":
        pu=d.get("pro_access_until")
        pro[n]=(str(pu)[:10] if pu else "")
rows=[]
for n,v in acc.items():
    try: b=float(v["bal"])
    except: b=0.0
    rows.append((b,n,pro.get(n,""),v["key"]))
rows.sort(key=lambda r:(-r[0], r[1]))
with open("ob_login_list.txt","w") as f:
    f.write("# obscurify — daftar LOGIN (nomor akun = kunci login, TIDAK ada email/password)\n")
    f.write("# login: https://obscurify.ai -> masukkan nomor akun\n")
    f.write(f"# audit 2026-11-17 | total {len(rows)} akun\n")
    f.write("# nomor_akun | saldo | pro_aktif_sampai\n")
    for b,n,p,k in rows: f.write(f"{n} | ${b:.2f} | {p or '-'}\n")
print(f"total {len(rows)} akun | bersaldo {sum(1 for r in rows if r[0]>0)} | total ${sum(r[0] for r in rows):.2f}")
for b,n,p,k in rows[:5]: print(f"  {n} | ${b:.2f} | pro {p or '-'}")
